const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;
const W=960,H=540,T=24,WW=150,WH=48;const colors={};
const ID={air:0,grass:1,dirt:2,stone:3,copper:4,coal:5,wood:6,leaf:7,bench:8,torch:9};
const tileNames={1:'Turf',2:'Dirt',3:'Stone',4:'Copper ore',5:'Coal',6:'Log',7:'Leaves',8:'Workbench',9:'Torch'};
let world=[],surface=[],seed=Math.random()*999999|0,cam={x:0,y:0},running=false,last=0,clock=480,day=1,selected=0,mouse={x:0,y:0,down:false,right:false},toastTimer=0,saveTimer=0,mineTimer=0,attackTimer=0,craftOpen=false,worldTime=0;
const items=[{id:'pick',name:'Stone pick',icon:'⛏',count:1},{id:'sword',name:'Wood sword',icon:'⚔',count:1},{id:2,name:'Dirt',icon:'🟫',count:0},{id:6,name:'Log',icon:'🪵',count:0},{id:3,name:'Stone',icon:'⬜',count:0},{id:4,name:'Copper',icon:'🟠',count:0}];
let player={x:12*T,y:0,vx:0,vy:0,w:15,h:31,health:5,maxHealth:5,hunger:100,onGround:false,face:1,invuln:0,anim:0};let mobs=[],particles=[],down={},touchState={};
const rand=(x,y=0)=>{let n=Math.sin((x+seed*.013)*127.1+(y+seed*.0001)*311.7)*43758.5453;return n-Math.floor(n)};
function makeWorld(){world=Array.from({length:WH},()=>new Uint8Array(WW));surface=[];let h=17;for(let x=0;x<WW;x++){h+=Math.round((rand(x,12)-.5)*2);h=Math.max(13,Math.min(21,h));surface[x]=h;for(let y=h;y<WH;y++){let v=ID.dirt;if(y===h)v=ID.grass;else if(y>h+5)v=ID.stone;if(y>h+7&&rand(x,y)>.967)v=ID.copper;if(y>h+9&&rand(x+7,y)>.974)v=ID.coal;world[y][x]=v}}
// surface trees and flowers
for(let x=4;x<WW-3;x++){if(rand(x,81)>.89&&Math.abs(surface[x]-surface[x+1])<2){let sy=surface[x],ht=3+(rand(x,7)*3|0);for(let y=1;y<=ht;y++)world[sy-y][x]=ID.wood;for(let yy=sy-ht-2;yy<=sy-ht+1;yy++)for(let xx=x-2;xx<=x+2;xx++)if(yy>=0&&rand(xx,yy)>.21&&Math.abs(xx-x)+Math.abs(yy-(sy-ht))<4)world[yy][xx]=ID.leaf}}
// spawn point clearing
for(let x=10;x<15;x++)for(let y=surface[x]-5;y<surface[x];y++)if(world[y])world[y][x]=0;
}
function tile(x,y){if(x<0||x>=WW||y<0)return ID.stone;if(y>=WH)return ID.stone;return world[y][x]}
function setTile(x,y,id){if(x>=0&&x<WW&&y>=0&&y<WH)world[y][x]=id}
function resetGame(){makeWorld();player.x=12*T;player.y=(surface[12]-2)*T-31;player.vx=player.vy=0;player.health=5;player.hunger=100;clock=480;day=1;mobs=[];items.forEach((it,i)=>it.count=[1,1,8,2,0,0][i]);loadSave()}
function sky(){let phase=clock/1440,daylight=Math.max(0,Math.sin((phase-.25)*Math.PI*2));let night=1-daylight;let top=lerpColor('#16243c','#7cc9d4',daylight),bottom=lerpColor('#253650','#d7edcf',daylight);let g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,top);g.addColorStop(1,bottom);ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
if(night>.25){ctx.globalAlpha=night*.9;for(let i=0;i<60;i++){let x=(i*173+20-cam.x*.08)%W,y=(i*79+14)%215;ctx.fillStyle='#fff4c4';ctx.fillRect((x+W)%W,y,2,2)}ctx.globalAlpha=1}
// distant layered hills
for(let layer=0;layer<3;layer++){ctx.fillStyle=['#34576a','#385b5a','#536e4d'][layer];ctx.beginPath();ctx.moveTo(0,H);let scroll=cam.x*(.12+layer*.12);for(let x=-30;x<=W+40;x+=35){let wx=x+scroll;let yy=255+layer*42+Math.sin(wx*.008+layer)*36+Math.sin(wx*.021)*15;ctx.lineTo(x,yy)}ctx.lineTo(W,H);ctx.fill()}
}
function lerpColor(a,b,t){let A=parseInt(a.slice(1),16),B=parseInt(b.slice(1),16),r=Math.round(((A>>16)&255)*(1-t)+((B>>16)&255)*t),g=Math.round(((A>>8)&255)*(1-t)+((B>>8)&255)*t),bl=Math.round((A&255)*(1-t)+(B&255)*t);return `rgb(${r},${g},${bl})`}
function drawTile(id,x,y,tx,ty){let px=x*T-cam.x,py=y*T-cam.y;let variation=rand(x,ty*17+y);let palette={1:['#76533a','#7f6041'],2:['#79533b','#825b40'],3:['#555e61','#62696a'],4:['#555c5b','#626b68'],5:['#4c5558','#5c6262'],6:['#795035','#8c5c37'],7:['#397754','#43835a'],8:['#a77342','#c18b50'],9:['#69563c','#796343']};let base=palette[id];ctx.fillStyle=base?base[variation>.5?0:1]:'#000';ctx.fillRect(px,py,T,T);
if(id===ID.grass){ctx.fillStyle='#5eab64';ctx.fillRect(px,py,T,5);ctx.fillStyle='#79c56e';ctx.fillRect(px+2,py+1,5,2);ctx.fillRect(px+15,py+2,4,2)}
if(id===ID.dirt||id===ID.stone){ctx.fillStyle=id===ID.dirt?'#9b714c':'#828889';for(let i=0;i<3;i++){let ax=px+3+rand(x+i,ty)*17|0,ay=py+5+rand(y+i,x)*15|0;ctx.fillRect(ax,ay,2,2)}}
if(id===ID.copper||id===ID.coal){let c=id===ID.copper?'#d18a53':'#252e32';ctx.fillStyle=c;ctx.fillRect(px+5,py+5,6,5);ctx.fillRect(px+13,py+11,5,6);ctx.fillRect(px+4,py+16,4,3);ctx.fillStyle=id===ID.copper?'#efb16a':'#818b88';ctx.fillRect(px+7,py+6,2,2)}
if(id===ID.wood){ctx.fillStyle='#a67443';ctx.fillRect(px+5,py,4,T);ctx.fillRect(px+16,py,3,T)}
if(id===ID.leaf){ctx.fillStyle='#60a864';ctx.fillRect(px+4,py+4,12,10);ctx.fillRect(px+1,py+9,21,8);ctx.fillStyle='#82c66c';ctx.fillRect(px+5,py+5,5,3)}
if(id===ID.bench){ctx.fillStyle='#5e402e';ctx.fillRect(px+3,py+10,18,4);ctx.fillRect(px+5,py+14,3,9);ctx.fillRect(px+16,py+14,3,9);ctx.fillStyle='#d5a65f';ctx.fillRect(px+4,py+8,16,3)}
if(id===ID.torch){ctx.fillStyle='#8c613c';ctx.fillRect(px+11,py+9,3,14);ctx.fillStyle='#ffd26c';ctx.fillRect(px+9,py+4,7,7);ctx.fillStyle='#fff1a4';ctx.fillRect(px+11,py+2,3,4)}
