function drawWorld(){let minX=Math.max(0,Math.floor(cam.x/T)-1),maxX=Math.min(WW,Math.ceil((cam.x+W)/T)+1),minY=Math.max(0,Math.floor(cam.y/T)-1),maxY=Math.min(WH,Math.ceil((cam.y+H)/T)+1);for(let y=minY;y<maxY;y++)for(let x=minX;x<maxX;x++){let id=world[y][x];if(id)drawTile(id,x,y)}
// soft darkness below ground
let night=Math.max(0,1-Math.max(0,Math.sin((clock/1440-.25)*Math.PI*2)));if(night>.45){ctx.fillStyle=`rgba(12,18,31,${(night-.45)*.55})`;ctx.fillRect(0,0,W,H)}
// torch warmth
for(let y=minY;y<maxY;y++)for(let x=minX;x<maxX;x++)if(world[y][x]===ID.torch){let px=x*T-cam.x+12,py=y*T-cam.y+10,g=ctx.createRadialGradient(px,py,4,px,py,90);g.addColorStop(0,'#ffb54830');g.addColorStop(1,'#ffb54800');ctx.fillStyle=g;ctx.fillRect(px-90,py-90,180,180)}
}

