function drawPlayer(){let x=player.x-cam.x,y=player.y-cam.y;let stride=player.onGround&&Math.abs(player.vx)>10?Math.sin(player.anim*15)*3:0;ctx.save();if(player.face<0){ctx.translate(x+player.w,y);ctx.scale(-1,1);x=0;y=0}else{ctx.translate(x,y);x=0;y=0}
// shadow + boots
ctx.fillStyle='#18252b66';ctx.fillRect(x-4,y+player.h-2,player.w+8,4);ctx.fillStyle='#4b3b38';ctx.fillRect(x+2+stride,y+25,5,6);ctx.fillRect(x+9-stride,y+25,5,6);
// body
ctx.fillStyle='#d5a35b';ctx.fillRect(x+2,y+12,12,13);ctx.fillStyle='#498b74';ctx.fillRect(x+2,y+16,12,8);ctx.fillStyle='#e3b978';ctx.fillRect(x+3,y+2,11,11);ctx.fillStyle='#71473c';ctx.fillRect(x+2,y,12,5);ctx.fillRect(x,y+3,4,4);ctx.fillStyle='#263a3c';ctx.fillRect(x+10,y+6,2,2);ctx.fillStyle='#f0cf92';ctx.fillRect(x+5,y+7,4,2);
// held tool
ctx.fillStyle='#9b7049';ctx.fillRect(x+14,y+15,3,10);ctx.fillStyle='#a8afb0';ctx.fillRect(x+11,y+13,9,3);ctx.restore();if(player.invuln>0&&Math.floor(worldTime*14)%2)ctx.globalAlpha=.4;ctx.fillStyle='#fff';if(player.invuln>0){ctx.fillStyle='#ff777788';ctx.fillRect(player.x-cam.x-3,player.y-cam.y-3,player.w+6,player.h+6)}ctx.globalAlpha=1}
function drawMobs(){for(const m of mobs){let x=m.x-cam.x,y=m.y-cam.y;ctx.fillStyle='#12232d55';ctx.fillRect(x-3,y+m.h-1,m.w+6,4);ctx.fillStyle=m.hurt>0?'#fff':'#86bd72';ctx.fillRect(x+2,y+5,m.w-4,m.h-5);ctx.fillRect(x+5,y+1,m.w-10,6);ctx.fillStyle='#d8e9a1';ctx.fillRect(x+5,y+8,3,3);ctx.fillRect(x+m.w-8,y+8,3,3);ctx.fillStyle='#263336';ctx.fillRect(x+6,y+9,2,2);ctx.fillRect(x+m.w-7,y+9,2,2)}}
function drawParticles(dt){for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=80*dt;p.life-=dt;ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.fillRect(p.x-cam.x,p.y-cam.y,p.size,p.size);if(p.life<=0)particles.splice(i,1)}ctx.globalAlpha=1}
function blocksAt(px,py,w,h){let list=[];for(let ty=Math.floor(py/T);ty<=Math.floor((py+h-1)/T);ty++)for(let tx=Math.floor(px/T);tx<=Math.floor((px+w-1)/T);tx++)if(tile(tx,ty))list.push({tx,ty});return list}
function update(dt){worldTime+=dt;clock+=dt*2.7;if(clock>=1440){clock-=1440;day++;showToast(`Day ${day} begins · Keep exploring!`);player.hunger=Math.min(100,player.hunger+12)}player.anim+=dt;player.invuln=Math.max(0,player.invuln-dt);player.hunger=Math.max(0,player.hunger-dt*.42);if(player.hunger<=0&&Math.floor(worldTime*2)%2===0&&player.health>1)player.health-=.006;
let move=(down.ArrowLeft||down.a||touchState.left?-1:0)+(down.ArrowRight||down.d||touchState.right?1:0);player.vx=move*145;if(move)player.face=move;let jump=down[' ']||down.ArrowUp||down.w||touchState.jump;if(jump&&player.onGround){player.vy=-350;player.onGround=false}
player.vy=Math.min(560,player.vy+900*dt);player.x+=player.vx*dt;player.x=Math.max(0,Math.min(WW*T-player.w,player.x));for(let b of blocksAt(player.x,player.y,player.w,player.h)){if(player.vx>0)player.x=b.tx*T-player.w;else if(player.vx<0)player.x=(b.tx+1)*T}player.y+=player.vy*dt;player.onGround=false;for(let b of blocksAt(player.x,player.y,player.w,player.h)){if(player.vy>0){player.y=b.ty*T-player.h;player.vy=0;player.onGround=true}else if(player.vy<0){player.y=(b.ty+1)*T;player.vy=0}}
// camera follow
cam.x=Math.max(0,Math.min(WW*T-W,player.x+player.w/2-W/2));cam.y=Math.max(0,Math.min(WH*T-H,player.y+player.h/2-H*.52));
updateMobs(dt);if(mouse.down||touchState.mine)mine(dt);if(mouse.right||touchState.place)place();if(attackTimer>0)attackTimer-=dt;mineTimer=Math.max(0,mineTimer-dt);saveTimer+=dt;if(saveTimer>8){saveTimer=0;saveGame()}
