function renderHotbar(){let bar=document.getElementById('hotbar');bar.innerHTML='';items.forEach((it,i)=>{let el=document.createElement('div');el.className='slot'+(i===selected?' active':'');el.innerHTML=`<b>${i+1}</b>${it.icon}<small>${it.count||''}</small>`;el.title=it.name;el.onclick=()=>{selected=i;renderHotbar()};bar.appendChild(el)})}
function updateStatus(){let hearts=Math.ceil(player.health);document.getElementById('health').innerHTML='♥'.repeat(hearts)+'<span style="opacity:.24">'+'♥'.repeat(player.maxHealth-hearts)+'</span>';let foods=Math.ceil(player.hunger/25);document.getElementById('food').innerHTML='◆'.repeat(foods)+'<span style="opacity:.2">'+'◆'.repeat(4-foods)+'</span>';let hh=Math.floor(clock/60),mm=Math.floor(clock%60),night=clock>1120||clock<300;document.getElementById('clock').textContent=`${night?'☾ NIGHT':'☀ DAY'} ${String(hh%24).padStart(2,'0')}:${String(mm).padStart(2,'0')}`;document.getElementById('dayNum').textContent=day}
function showToast(msg){let el=document.getElementById('toast');el.textContent=msg;el.style.opacity=1;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.opacity=0,1700)}
function recipeUI(){let root=document.getElementById('recipes'),recipes=[{name:'Workbench',icon:'🪚',cost:[[6,4]],out:8,n:1},{name:'Torch bundle',icon:'🔥',cost:[[6,1]],out:9,n:3},{name:'Stone pick',icon:'⛏',cost:[[3,5],[6,2]],out:'pick',n:1},{name:'Wood sword',icon:'⚔',cost:[[6,4]],out:'sword',n:1},{name:'Trail snack',icon:'🍎',cost:[[6,2]],out:'food',n:1}];root.innerHTML='';for(let r of recipes){let ready=r.cost.every(([id,n])=>items.find(i=>i.id===id)?.count>=n);let row=document.createElement('div');row.className='craftrow';let text=r.cost.map(([id,n])=>`${n} ${id===6?'log':id===3?'stone':'resource'}${n>1?'s':''}`).join(' + ');row.innerHTML=`<span>${r.icon} ${r.name}<br><span style="opacity:.65;font-size:9px">${text}</span></span><button ${ready?'':'disabled'}>${r.out==='food'?'EAT':'CRAFT'}</button>`;row.querySelector('button').onclick=()=>craft(r);root.appendChild(row)}}
function craft(r){if(!r.cost.every(([id,n])=>items.find(i=>i.id===id)?.count>=n))return;for(let [id,n] of r.cost)items.find(i=>i.id===id).count-=n;if(r.out==='food'){player.hunger=Math.min(100,player.hunger+35);showToast('Trail snack eaten · hunger restored')}else if(r.out==='pick'||r.out==='sword'){items.find(i=>i.id===r.out).count=1;showToast(`${r.name} crafted!`)}else{items.find(i=>i.id===r.out).count+=r.n;showToast(`${r.name} crafted!`)}renderHotbar();updateStatus();recipeUI();saveGame()}
function openCraft(){craftOpen=!craftOpen;document.getElementById('craft').style.display=craftOpen?'block':'none';if(craftOpen)recipeUI()}
function saveGame(){try{localStorage.setItem('littleEmberSave',JSON.stringify({seed,world:world.map(r=>Array.from(r)),player:{x:player.x,y:player.y,health:player.health,hunger:player.hunger},items:items.map(i=>i.count),clock,day}))}catch(e){}}
function loadSave(){try{let s=JSON.parse(localStorage.getItem('littleEmberSave')||'null');if(!s)return;if(s.world?.length===WH&&s.world[0]?.length===WW){seed=s.seed;world=s.world.map(r=>Uint8Array.from(r));player.x=s.player.x;player.y=s.player.y;player.health=s.player.health;player.hunger=s.player.hunger;items.forEach((it,i)=>it.count=s.items[i]??it.count);clock=s.clock;day=s.day;showToast('Your saved wilds are ready')}}catch(e){}}
function gameOver(){running=false;saveGame();let card=document.querySelector('#modal .card');card.innerHTML='<div class="eyebrow">THE WILDS WILL WAIT</div><h1>EMBER OUT</h1><p>Your journey ends here, but the world remembers what you built.</p><button class="btn" id="restartBtn">TRY AGAIN</button><div class="tiny">Your world and gathered items remain saved.</div>';document.getElementById('modal').style.display='grid';document.getElementById('restartBtn').onclick=()=>{player.health=5;player.hunger=80;player.x=12*T;player.y=(surface[12]-2)*T-31;player.vy=0;mobs=[];running=true;document.getElementById('modal').style.display='none';last=performance.now();requestAnimationFrame(loop)}}
function drawTarget(){if(!mouse.down)return;let t=targetTile();if(!t||!t.id)return;ctx.strokeStyle='#ffe18a';ctx.lineWidth=2;ctx.strokeRect(t.tx*T-cam.x+2,t.ty*T-cam.y+2,T-4,T-4)}
function frame(dt){update(dt);sky();drawWorld();drawParticles(dt);drawMobs();drawPlayer();drawTarget();updateStatus()}
function loop(now){if(!running)return;let dt=Math.min(.04,(now-last)/1000||0);last=now;frame(dt);requestAnimationFrame(loop)}

