function loadSave(){try{let s=JSON.parse(localStorage.getItem('littleEmberSave')||'null');if(!s)return;if(s.world?.length===WH&&s.world[0]?.length===WW){seed=s.seed;world=s.world.map(r=>Uint8Array.from(r));player.x=s.player.x;player.y=s.player.y;player.health=s.player.health;player.hunger=s.player.hunger;items.forEach((it,i)=>it.count=s.items[i]??it.count);clock=s.clock;day=s.day;showToast('Your saved wilds are ready')}}catch(e){}}
function gameOver(){running=false;saveGame();let card=document.querySelector('#modal .card');card.innerHTML='<div class="eyebrow">THE WILDS WILL WAIT</div><h1>EMBER OUT</h1><p>Your journey ends here, but the world remembers what you built.</p><button class="btn" id="restartBtn">TRY AGAIN</button><div class="tiny">Your world and gathered items remain saved.</div>';document.getElementById('modal').style.display='grid';document.getElementById('restartBtn').onclick=()=>{player.health=5;player.hunger=80;player.x=12*T;player.y=(surface[12]-2)*T-31;player.vy=0;mobs=[];running=true;document.getElementById('modal').style.display='none';last=performance.now();requestAnimationFrame(loop)}}
function drawTarget(){if(!mouse.down)return;let t=targetTile();if(!t||!t.id)return;ctx.strokeStyle='#ffe18a';ctx.lineWidth=2;ctx.strokeRect(t.tx*T-cam.x+2,t.ty*T-cam.y+2,T-4,T-4)}
function frame(dt){update(dt);sky();drawWorld();drawParticles(dt);drawMobs();drawPlayer();drawTarget();updateStatus()}
function loop(now){if(!running)return;let dt=Math.min(.04,(now-last)/1000||0);last=now;frame(dt);requestAnimationFrame(loop)}
function pointer(e){let r=canvas.getBoundingClientRect();mouse.x=(e.clientX-r.left)*W/r.width;mouse.y=(e.clientY-r.top)*H/r.height}
canvas.addEventListener('pointermove',pointer);canvas.addEventListener('pointerdown',e=>{e.preventDefault();pointer(e);if(e.button===2){mouse.right=true;place()}else{mouse.down=true;attack();mineTimer=0}});window.addEventListener('pointerup',e=>{if(e.button===0)mouse.down=false;if(e.button===2)mouse.right=false});canvas.addEventListener('contextmenu',e=>e.preventDefault());
window.addEventListener('keydown',e=>{let k=e.key.toLowerCase();down[k]=true;if([' ','arrowup','arrowleft','arrowright'].includes(k))e.preventDefault();if(k>='1'&&k<='8'){selected=Number(k)-1;renderHotbar()}if(k==='c'&&!e.repeat)openCraft();if(k==='e'&&!e.repeat){player.hunger=Math.min(100,player.hunger+25);updateStatus();showToast('A little food for the road.')}if(k==='escape'&&craftOpen)openCraft();if(k==='enter'&&!running&&document.getElementById('modal').style.display!=='none')startGame()});window.addEventListener('keyup',e=>down[e.key.toLowerCase()]=false);
document.querySelectorAll('[data-hold]').forEach(el=>{let key=el.dataset.hold;el.addEventListener('pointerdown',e=>{e.preventDefault();touchState[key]=true});for(let ev of ['pointerup','pointercancel','pointerleave'])el.addEventListener(ev,()=>touchState[key]=false)});document.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('pointerdown',e=>{e.preventDefault();touchState[el.dataset.action]=true;setTimeout(()=>touchState[el.dataset.action]=false,180)}));
function startGame(){document.getElementById('modal').style.display='none';running=true;last=performance.now();requestAnimationFrame(loop)}document.getElementById('startBtn').onclick=()=>startGame();
function resetGame(){makeWorld();player.x=12*T;player.y=(surface[12]-2)*T-31;player.vx=player.vy=0;player.health=5;player.hunger=100;clock=480;day=1;mobs=[];items.forEach((it,i)=>it.count=[1,1,8,2,0,0,0,0][i]);loadSave()}
